pub fn dump_Mark2Record2(
    out: &mut impl Write,
    path: &str,
    value: &Mark2Record2<'_>,
    base: FontData<'_>,
) -> io::Result<()> {
    let dump_args = crate::dump_support::arguments();
    if !crate::dump_support::enter(path) {
        return writeln!(out, "{path}=traversal-limit");
    }
    {
        let path = &format!("{path}.mark2AnchorOffsets");
        let fieldValue = value.mark2_anchor_offsets();
        writeln!(out, "{path}.length={}", fieldValue.len())?;
        for (index, item) in fieldValue.iter().enumerate() {
            let path = &format!("{path}[{index}]");
            let item = item.get();
            writeln!(out, "{path}={}", item.offset().to_u32())?;
        }
    }
    {
        let path = &format!("{path}.mark2Anchors");
        let target_args: [u64; 3] = [0, 0, 0];
        let resolvedArray = value.mark2_anchors(base);
        writeln!(out, "{path}.length={}", resolvedArray.len())?;
        for index in 0..resolvedArray.len() {
            let path = &format!("{path}[{index}]");
            crate::dump_support::set_arguments(target_args);
            match resolvedArray.get(index) {
                None => writeln!(out, "{path}=none")?,
                Some(resolved) => match resolved {
                    Ok(table) => table.dump(out, path)?,
                    Err(error) => writeln!(out, "{path}.error={}", crate::error(error))?,
                },
            }
        }
    }
    Ok(())
}

pub fn dump_MarkArray2(out: &mut impl Write, path: &str, value: &MarkArray2<'_>) -> io::Result<()> {
    let dump_args = crate::dump_support::arguments();
    if !crate::dump_support::visit(out, path, 1508449440, value.offset_data().len(), dump_args)? {
        return Ok(());
    }
    let base = value.offset_data();
    {
        let path = &format!("{path}.markCount");
        let fieldValue = value.mark_count();
        writeln!(out, "{path}={}", fieldValue.to_u32())?;
    }
    {
        let path = &format!("{path}.markRecords");
        let fieldValue = value.mark_records();
        writeln!(out, "{path}.length={}", fieldValue.len())?;
        for (index, item) in fieldValue.iter().enumerate() {
            let path = &format!("{path}[{index}]");
            crate::dump_support::set_arguments([0; 3]);
            dump_MarkRecord2(out, path, item, base)?;
        }
    }
    Ok(())
}

impl DumpTable for MarkArray2<'_> {
    fn dump(&self, out: &mut impl Write, path: &str) -> io::Result<()> {
        dump_MarkArray2(out, path, self)
    }
}

