pub fn dump_tables(
    out: &mut impl Write,
    path: &str,
    font: &read_fonts::FontRef<'_>,
) -> io::Result<()> {
    use read_fonts::FontRead;
    {
        crate::dump_support::begin_table();
        let path = &format!("{path}.GPOS");
        let tag = Tag::new(b"GPOS");
        match font
            .table_data(tag)
            .ok_or(ReadError::TableIsMissing(tag))
            .and_then(Gpos::read)
        {
            Ok(table) => dump_Gpos(out, path, &table)?,
            Err(error) => writeln!(out, "{path}.error={}", crate::error(error))?,
        }
    }
    Ok(())
}

